{
  "outcome": "escalate",
  "rationale": "This claim must be escalated because an automated fraud flag was raised for an inflated estimate. Section 7.3 governs this situation when the claimed amount is substantially higher than the usual cost of repair.",
  "citations": [
    {
      "clause_id": "STD-7.3",
      "quote": "If the amount claimed is substantially higher than the usual cost of repairing the damage described, or is not supported by the itemized estimate, the claim must be escalated for review."
    }
  ]
}
